import{z as n,x as B,o as A,c as d,q as r,j as i,D as t,d as e,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"四次挥手与 TIME_WAIT","description":"","frontmatter":{"title":"四次挥手与 TIME_WAIT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-time-wait.md","filePath":"cs/tcp-time-wait.md","lastUpdated":1791063341000}'),I={name:"cs/tcp-time-wait.md"};function T(p,a,_,m,D,C){const s=B("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="四次挥手与-time-wait" tabindex="-1">四次挥手与 TIME_WAIT <a class="header-anchor" href="#四次挥手与-time-wait" aria-label="Permalink to &quot;四次挥手与 TIME_WAIT&quot;">​</a></h1><div class="epigraph"><p>连接的两端各自关闭发送方向；主动关闭的一方在 TIME_WAIT 里停留 2MSL，让迟到的报文自然死掉。</p><footer>—— 据 Postel, RFC 793；Kurose and Ross 对连接拆除的整理</footer></div><p><a href="/cs/tcp-handshake">上一课</a>用三次握手同步了 ISN，连接进入已建立。本课不重画 SYN 交换。缺口是拆除：TCP 是全双工，一侧 FIN 只表示「我不再发」。主动关闭方必须处理旧连接的迟到包与对端最后 ACK 的丢失。TIME_WAIT 是这份合同，不是内核随意占着端口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>握手建立的是两条方向的序号空间。关闭：FIN 与 ACK 各来一回，共四段（可合并成三次，语义仍是两边关发送）。若主动方在收到最后 ACK 后立刻释放四元组，迟到的 FIN 或数据可能被新连接（同一四元组复用）当成合法。RFC 793：在 TIME_WAIT 保持 2MSL。缺口是<strong>拆除与四元组回收</strong>，不是重传定时器公式。</p><p><span class="marginnote">MSL 是报文最大生存时间的约定。RST 可以更快拆掉，但不代替正常 FIN 对未读数据的交付。半关闭允许一边仍发。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用 <code>close</code> 或 shutdown 发送方向 → 发 FIN。对端 ACK，自己还可发送直到也 FIN。主动方进入 TIME_WAIT，丢弃迟到段或应答，到期后删除控制块。重传丢失的最后 ACK 靠对端重传 FIN。本课不把同时打开/同时关闭的全部状态图画成考试默写。</p>',8)),(A(),i(l,null,{default:t(()=>[o(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22%E5%B7%B2%E5%BB%BA%E7%AB%8B%22%5D%20--%3E%20FIN1%5B%22%E4%B8%80%E4%BE%A7%20FIN%22%5D%0A%20%20FIN1%20--%3E%20HALF%5B%22%E5%8D%8A%E5%85%B3%E9%97%AD%22%5D%0A%20%20HALF%20--%3E%20FIN2%5B%22%E5%8F%A6%E4%B8%80%E4%BE%A7%20FIN%22%5D%0A%20%20FIN2%20--%3E%20TW%5B%22TIME_WAIT%202MSL%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},'数字实例：常见实现把 MSL 定为 30 秒，主动关闭方因此在 TIME_WAIT 停留 2×30=60 秒；高并发短连接客户端"临时端口耗尽"，多半就是这 60 秒攒出来的。')],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("TIME_WAIT 把"),E("a",{href:"/cs/layering-e2e"},"端到端"),e("的「旧段不能冒充新流」落在时间上，因为 IP 没有连接 ID 世代号（后课 QUIC 才有连接标识）。端口耗尽是它的运营症状，不是协议写错。序号与重传下一课才保证数据平面可靠；拆除课只保证状态机不把尸体当新生儿。")],-1)),a[6]||(a[6]=E("p",null,"2MSL 这段停留到底挡住什么？拆开看是两类风险，TIME_WAIT 一并兜住：",-1)),(A(),i(l,null,{default:t(()=>[o(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIN%5B%22%E8%A2%AB%E5%8A%A8%E6%96%B9%E5%8F%91%E5%87%BA%E6%9C%80%E5%90%8E%E7%9A%84%20FIN%22%5D%20--%3E%20L%7B%22%E6%9C%80%E5%90%8E%E7%9A%84%20ACK%20%E4%B8%A2%E4%BA%86%3F%22%7D%0A%20%20L%20--%3E%7C%22%E6%98%AF%22%7C%20RE%5B%22%E8%A2%AB%E5%8A%A8%E6%96%B9%E9%87%8D%E4%BC%A0%20FIN%22%5D%0A%20%20RE%20--%3E%20AW%5B%22TIME_WAIT%20%E4%B8%AD%E7%9A%84%E4%B8%BB%E5%8A%A8%E6%96%B9%E8%A1%A5%E5%8F%91%20ACK%22%5D%0A%20%20L%20--%3E%7C%22%E5%90%A6%2C%20%E6%AD%A3%E5%B8%B8%E6%94%B6%E5%88%B0%22%7C%20OLD%5B%22%E6%97%A7%E8%BF%9E%E6%8E%A5%E7%9A%84%E8%BF%9F%E5%88%B0%E6%AE%B5%E9%99%86%E7%BB%AD%E5%88%B0%E8%BE%BE%22%5D%0A%20%20OLD%20--%3E%20DP%5B%22%E8%A2%AB%E8%AF%86%E5%88%AB%E4%B8%BA%E6%97%A7%E6%B5%81%2C%20%E7%9B%B4%E6%8E%A5%E4%B8%A2%E5%BC%83%22%5D%0A%20%20AW%20--%3E%20EX%5B%222MSL%20%E5%88%B0%E6%9C%9F%2C%20%E5%9B%9B%E5%85%83%E7%BB%84%E6%89%8D%E5%9B%9E%E6%94%B6%22%5D%0A%20%20DP%20--%3E%20EX%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">为什么重要：若收到最后 ACK 就立刻释放四元组，随后复用同一四元组的新连接可能收到旧连接迟到的数据——序号恰好落进新窗口时，旧字节会被当成新字节，比丢包破坏大得多。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SO_REUSEADDR 的全部平台语义当标准，不把负载均衡器上的四元组规模写成调参手册。字节如何编号、丢了如何重发，下一课。</p><p>后课默认：连接能对称关闭，主动方会在 TIME_WAIT 停留。数据可靠是另一缺口。</p><p><span class="marginnote">常见误区：容易以为设了 SO_REUSEADDR 就能随意&quot;跳过 TIME_WAIT 重用端口&quot;。它放行的主要是绑定，旧段风险并没有消失，且各平台语义不一致，不能当万能开关。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四次挥手关两个方向；TIME_WAIT 挡迟到段。</li><li>半关闭合法；RST 是另一条路。</li><li>序号与重传下一课。</li><li>出处：RFC 793；Kurose and Ross。</li></ul>',7))])}const u=n(I,[["render",T]]);export{c as __pageData,u as default};
